import type { FastifyInstance, FastifyReply } from 'fastify'
import { z } from 'zod'
import { schemas, validateReviewResult, validateRunInputs } from '../contracts/projects/v1.ts'
import { eventSchema, workerResultSchema } from '../contracts/workflow/v1.ts'
import { ID_PATTERN } from './projectsConfig.ts'
import { DEFAULT_RUN_LIMIT, MAX_RUN_LIMIT, ProjectApiError, RunStore, compareRuns, decodeCursor, encodeCursor } from './projects.ts'

/**
 * The project-scoped read-only API from contracts/projects/README.md, mounted under /api/projects. Every
 * response is validated against the committed contract before it is sent; a projection that cannot satisfy the
 * contract is a 500, never a partial or fabricated payload. Errors use `{ error: { code, message } }` and never
 * name filesystem paths. Only GET/HEAD exist: any other method on these routes is a 405.
 */
export const PROJECTS_PREFIX = '/api/projects'
const READ_METHODS = 'GET, HEAD'
const OTHER_METHODS = ['POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'] as const

type ErrorBody = { error: { code: string; message: string } }

function errorBody(code: string, message: string): ErrorBody {
  return { error: { code, message } }
}

function sendError(reply: FastifyReply, status: number, code: string, message: string) {
  return reply.code(status).header('Cache-Control', 'no-store').send(errorBody(code, message))
}

function requireId(value: unknown, what: string): string {
  if (typeof value !== 'string' || !ID_PATTERN.test(value)) {
    throw new ProjectApiError(400, 'INVALID_ID', `The ${what} ID must be 1-128 characters of letters, digits, ".", "_" or "-", starting with a letter or digit.`)
  }
  return value
}

function single(value: unknown): unknown {
  return Array.isArray(value) ? (value.length === 1 ? value[0] : { duplicated: true }) : value
}

function parseLimit(value: unknown): number {
  const raw = single(value)
  if (raw === undefined) return DEFAULT_RUN_LIMIT
  if (typeof raw !== 'string' || !/^\d{1,3}$/.test(raw)) throw new ProjectApiError(400, 'INVALID_LIMIT', `The limit must be an integer from 1 to ${MAX_RUN_LIMIT}.`)
  const limit = Number(raw)
  if (limit < 1 || limit > MAX_RUN_LIMIT) throw new ProjectApiError(400, 'INVALID_LIMIT', `The limit must be an integer from 1 to ${MAX_RUN_LIMIT}.`)
  return limit
}

function parseAfter(value: unknown): number {
  const raw = single(value)
  if (raw === undefined) return 0
  if (typeof raw !== 'string' || !/^\d{1,15}$/.test(raw)) throw new ProjectApiError(400, 'INVALID_AFTER', 'The after parameter must be a non-negative integer event sequence.')
  return Number(raw)
}

function parseAttempt(value: unknown): number {
  if (typeof value !== 'string' || !/^[1-9]\d{0,8}$/.test(value)) throw new ProjectApiError(400, 'INVALID_ATTEMPT', 'The attempt must be a positive integer.')
  return Number(value)
}

/** Validates an outgoing payload against the contract; a violation is reported as a backend failure. */
function conform<T>(schema: z.ZodType<T>, payload: unknown, log: FastifyInstance['log']): T {
  const result = schema.safeParse(payload)
  if (!result.success) {
    log.error({ issues: result.error.issues.slice(0, 5).map(issue => `${issue.path.join('.')}: ${issue.message}`) }, 'Project API payload violates the contract')
    throw new ProjectApiError(500, 'RESPONSE_INVALID', 'The persisted run data could not be projected onto the API contract.')
  }
  return result.data
}

/** Applies a contract's cross-field validator to an outgoing payload; a violation is a backend failure, never a partial payload. */
function crossChecked<T>(validate: () => T, log: FastifyInstance['log']): T {
  try {
    return validate()
  } catch (error) {
    log.error({ message: (error as Error)?.message }, 'Project API payload violates a contract cross-field rule')
    throw new ProjectApiError(500, 'RESPONSE_INVALID', 'The persisted run data could not be projected onto the API contract.')
  }
}

export type ProjectRoutesOptions = { store: RunStore }

export async function projectRoutes(scope: FastifyInstance, options: ProjectRoutesOptions): Promise<void> {
  const { store } = options
  const log = scope.log
  scope.setNotFoundHandler((_request, reply) => sendError(reply, 404, 'NOT_FOUND', 'No project resource exists at that path.'))
  scope.setErrorHandler((error: unknown, _request, reply) => {
    if (error instanceof ProjectApiError) {
      if (error.status >= 500) log.error({ code: error.code, message: error.message }, 'Project API request failed')
      return sendError(reply, error.status, error.code, error.message)
    }
    const status = typeof (error as { statusCode?: number }).statusCode === 'number' ? (error as { statusCode: number }).statusCode : 500
    // Fastify caps path parameters below the contract's 128-character IDs; report that as an invalid ID, not a 414.
    if ((error as { code?: string }).code === 'FST_ERR_MAX_PARAM_LENGTH') return sendError(reply, 400, 'INVALID_ID', 'A path segment is longer than any valid ID.')
    if (status >= 400 && status < 500) return sendError(reply, status, 'BAD_REQUEST', 'The request could not be processed.')
    log.error({ code: (error as NodeJS.ErrnoException)?.code, message: (error as Error)?.message }, 'Unhandled project API failure')
    return sendError(reply, 500, 'INTERNAL', 'The request failed unexpectedly. Retry, then check the server log.')
  })
  scope.addHook('onSend', async (_request, reply) => {
    if (!reply.hasHeader('Cache-Control')) reply.header('Cache-Control', 'no-store')
  })

  const paths = {
    projects: '/',
    workflows: '/:project_id/workflows',
    runs: '/:project_id/workflows/:workflow_id/runs',
    run: '/:project_id/workflows/:workflow_id/runs/:run_id',
    events: '/:project_id/workflows/:workflow_id/runs/:run_id/events',
    result: '/:project_id/workflows/:workflow_id/runs/:run_id/results/:node_id/:attempt',
    artifact: '/:project_id/workflows/:workflow_id/runs/:run_id/artifacts/:artifact_id',
    review: '/:project_id/workflows/:workflow_id/runs/:run_id/reviews/:attempt',
    inputs: '/:project_id/workflows/:workflow_id/runs/:run_id/inputs',
  }
  for (const url of Object.values(paths)) {
    scope.route({
      method: [...OTHER_METHODS], url,
      handler: (_request, reply) => reply.header('Allow', READ_METHODS).code(405).send(errorBody('METHOD_NOT_ALLOWED', 'This project API is read-only: only GET and HEAD are supported.')),
    })
  }

  type Params = Record<string, string | undefined>
  const scopeOf = (params: Params) => store.scope(requireId(params.project_id, 'project'), requireId(params.workflow_id, 'workflow'))

  scope.get(paths.projects, async () => conform(schemas.projectList, { projects: store.projects() }, log))

  scope.get(paths.workflows, async request => {
    const { project_id } = request.params as Params
    return conform(schemas.workflowList, { workflows: store.workflows(requireId(project_id, 'project')) }, log)
  })

  scope.get(paths.runs, async request => {
    const run = scopeOf(request.params as Params)
    const query = request.query as Record<string, unknown>
    const limit = parseLimit(query.limit)
    const cursorValue = single(query.cursor)
    const cursor = cursorValue === undefined ? null : typeof cursorValue === 'string' && cursorValue.length > 0
      ? decodeCursor(cursorValue, { project_id: run.project.project_id, workflow_id: run.workflow.workflow_id })
      : (() => { throw new ProjectApiError(400, 'INVALID_CURSOR', 'The cursor is not a paging token issued for this workflow. Restart from the first page.') })()
    const all = await store.listRuns(run)
    const remaining = cursor ? all.filter(summary => compareRuns(summary, cursor) > 0) : all
    const page = remaining.slice(0, limit)
    const next_cursor = remaining.length > limit ? encodeCursor({ project_id: run.project.project_id, workflow_id: run.workflow.workflow_id }, page[page.length - 1]) : null
    return conform(schemas.runList, { runs: page, next_cursor }, log)
  })

  scope.get(paths.run, async request => {
    const params = request.params as Params
    const loaded = await store.loadRun(scopeOf(params), requireId(params.run_id, 'run'))
    return conform(schemas.runDetail, loaded.detail, log)
  })

  scope.get(paths.events, async request => {
    const params = request.params as Params
    const after = parseAfter((request.query as Record<string, unknown>).after)
    const loaded = await store.loadRun(scopeOf(params), requireId(params.run_id, 'run'))
    return conform(z.strictObject({ events: z.array(eventSchema) }), { events: loaded.events.filter(event => event.sequence > after) }, log)
  })

  scope.get(paths.result, async request => {
    const params = request.params as Params
    const runScope = scopeOf(params)
    const runId = requireId(params.run_id, 'run')
    const nodeId = requireId(params.node_id, 'node')
    const attempt = parseAttempt(params.attempt)
    return conform(workerResultSchema, await store.workerResult(runScope, runId, nodeId, attempt), log)
  })

  scope.get(paths.review, async request => {
    const params = request.params as Params
    const runScope = scopeOf(params)
    const runId = requireId(params.run_id, 'run')
    const attempt = parseAttempt(params.attempt)
    const review = await store.reviewResult(runScope, runId, attempt)
    return conform(schemas.reviewResult, crossChecked(() => validateReviewResult(review), log), log)
  })

  scope.get(paths.inputs, async request => {
    const params = request.params as Params
    const inputs = await store.runInputs(scopeOf(params), requireId(params.run_id, 'run'))
    return conform(schemas.runInputs, crossChecked(() => validateRunInputs(inputs), log), log)
  })

  scope.get(paths.artifact, async (request, reply) => {
    const params = request.params as Params
    const runScope = scopeOf(params)
    const runId = requireId(params.run_id, 'run')
    const artifactId = requireId(params.artifact_id, 'artifact')
    const artifact = await store.artifact(runScope, runId, artifactId)
    return reply
      .header('Content-Type', artifact.contentType)
      .header('Content-Length', artifact.bytes.length)
      .header('X-Content-Type-Options', 'nosniff')
      .header('Content-Security-Policy', "default-src 'none'; sandbox")
      .header('Content-Disposition', `${artifact.disposition}; filename="${artifact.artifact_id}"`)
      .header('Cache-Control', 'no-store')
      .send(artifact.bytes)
  })
}

/**
 * Read-only client for the project workflow viewer API (`contracts/projects/README.md`).
 *
 * Every payload is validated against the committed contract schemas before it reaches a component. A
 * response that fails validation is a malformed-payload error: nothing is patched up or substituted.
 * Artifacts and results are only ever requested through the scoped routes of the run being viewed.
 */
import { z } from 'zod'
import { schemas, validateRunDetail, type Project, type RunDetail, type RunSummary, type WorkflowDefinition } from '../../contracts/projects/v1.ts'
import { eventSchema, validateWorkerResult, type WorkerResult, type WorkflowEvent } from '../../contracts/workflow/v1.ts'

export type { Project, RunDetail, RunSummary, WorkflowDefinition, WorkerResult, WorkflowEvent }

export type ApiErrorKind = 'network' | 'http' | 'malformed'

/** A failed request. `status` is set for HTTP failures; `code` comes from the contract error body when present. */
export class ProjectsApiError extends Error {
  readonly kind: ApiErrorKind
  readonly status: number | null
  readonly code: string | null
  readonly path: string

  constructor(kind: ApiErrorKind, message: string, path: string, options: { status?: number | null; code?: string | null } = {}) {
    super(message)
    this.name = 'ProjectsApiError'
    this.kind = kind
    this.status = options.status ?? null
    this.code = options.code ?? null
    this.path = path
  }

  get notFound(): boolean {
    return this.kind === 'http' && this.status === 404
  }
}

export function describeApiError(error: unknown): string {
  if (error instanceof ProjectsApiError) {
    switch (error.kind) {
      case 'network': return 'The API could not be reached. Check that the server is running, then retry.'
      case 'malformed': return `The API returned data that does not match the projects contract: ${error.message}`
      case 'http': return error.code ? `${error.message} (${error.code}, HTTP ${error.status})` : `${error.message} (HTTP ${error.status})`
    }
  }
  return error instanceof Error && error.message ? error.message : 'An unexpected error occurred.'
}

const errorBodySchema = z.object({ error: z.object({ code: z.string(), message: z.string() }) })

function encodeSegments(...segments: string[]): string {
  return segments.map(encodeURIComponent).join('/')
}

export type RunScope = { projectId: string; workflowId: string; runId: string }

export const paths = {
  projects: () => '/api/projects',
  workflows: (projectId: string) => `/api/projects/${encodeSegments(projectId)}/workflows`,
  runs: (projectId: string, workflowId: string, options: { limit?: number; cursor?: string | null } = {}) => {
    const query = new URLSearchParams()
    if (options.limit !== undefined) query.set('limit', String(options.limit))
    if (options.cursor) query.set('cursor', options.cursor)
    const suffix = query.size ? `?${query}` : ''
    return `/api/projects/${encodeSegments(projectId)}/workflows/${encodeSegments(workflowId)}/runs${suffix}`
  },
  run: (scope: RunScope) => `/api/projects/${encodeSegments(scope.projectId)}/workflows/${encodeSegments(scope.workflowId)}/runs/${encodeSegments(scope.runId)}`,
  events: (scope: RunScope, after = 0) => `${paths.run(scope)}/events?after=${after}`,
  result: (scope: RunScope, nodeId: string, attempt: number) => `${paths.run(scope)}/results/${encodeSegments(nodeId)}/${attempt}`,
  artifact: (scope: RunScope, artifactId: string) => `${paths.run(scope)}/artifacts/${encodeSegments(artifactId)}`,
}

async function request(path: string, signal: AbortSignal | undefined, accept: string): Promise<Response> {
  let response: Response
  try {
    response = await fetch(path, { signal, headers: { Accept: accept } })
  } catch (error) {
    if (signal?.aborted) throw error
    throw new ProjectsApiError('network', error instanceof Error ? error.message : 'Network failure', path)
  }
  if (!response.ok) {
    let body: unknown = null
    try { body = await response.json() } catch { /* not JSON */ }
    const parsed = errorBodySchema.safeParse(body)
    const message = parsed.success ? parsed.data.error.message : `The API responded with status ${response.status}.`
    throw new ProjectsApiError('http', message, path, { status: response.status, code: parsed.success ? parsed.data.error.code : null })
  }
  return response
}

async function requestJson<T>(path: string, validate: (input: unknown) => T, signal?: AbortSignal): Promise<T> {
  const response = await request(path, signal, 'application/json')
  let body: unknown
  try {
    body = await response.json()
  } catch {
    throw new ProjectsApiError('malformed', 'the response body is not JSON.', path)
  }
  try {
    return validate(body)
  } catch (error) {
    throw new ProjectsApiError('malformed', error instanceof z.ZodError ? z.prettifyError(error) : error instanceof Error ? error.message : 'invalid payload', path)
  }
}

export function fetchProjects(signal?: AbortSignal): Promise<Project[]> {
  return requestJson(paths.projects(), input => schemas.projectList.parse(input).projects, signal)
}

export function fetchWorkflows(projectId: string, signal?: AbortSignal): Promise<WorkflowDefinition[]> {
  return requestJson(paths.workflows(projectId), input => schemas.workflowList.parse(input).workflows, signal)
}

export type RunPage = { runs: RunSummary[]; nextCursor: string | null }

export function fetchRuns(projectId: string, workflowId: string, options: { cursor?: string | null } = {}, signal?: AbortSignal): Promise<RunPage> {
  return requestJson(paths.runs(projectId, workflowId, options), input => {
    const page = schemas.runList.parse(input)
    for (const run of page.runs) {
      if (run.project_id !== projectId || run.workflow_id !== workflowId) throw new Error(`run ${run.run_id} belongs to another scope.`)
    }
    return { runs: page.runs, nextCursor: page.next_cursor }
  }, signal)
}

export function fetchRunDetail(scope: RunScope, signal?: AbortSignal): Promise<RunDetail> {
  return requestJson(paths.run(scope), input => {
    const detail = validateRunDetail(input)
    if (detail.summary.project_id !== scope.projectId || detail.summary.workflow_id !== scope.workflowId || detail.summary.run_id !== scope.runId) {
      throw new Error('the run detail belongs to a different project, workflow or run.')
    }
    return detail
  }, signal)
}

const eventListSchema = z.strictObject({ events: z.array(eventSchema) })

export function fetchEvents(scope: RunScope, signal?: AbortSignal): Promise<WorkflowEvent[]> {
  return requestJson(paths.events(scope, 0), input => {
    const events = eventListSchema.parse(input).events
    // Deduplicate by sequence and keep the persisted order; the run ID must be this run's.
    const seen = new Set<number>()
    const unique: WorkflowEvent[] = []
    for (const event of events) {
      if (event.run_id !== scope.runId) throw new Error(`event ${event.event_id} belongs to run ${event.run_id}.`)
      if (seen.has(event.sequence)) continue
      seen.add(event.sequence)
      unique.push(event)
    }
    return unique.sort((a, b) => a.sequence - b.sequence)
  }, signal)
}

/** Only results published under this run's scoped `results/` route are fetched; anything else is refused. */
export function scopedResultPath(scope: RunScope, resultUri: string): string | null {
  const prefix = `${paths.run(scope)}/results/`
  if (!resultUri.startsWith(prefix)) return null
  const rest = resultUri.slice(prefix.length).split('/')
  if (rest.length !== 2 || rest.some(segment => segment === '') || !/^[1-9][0-9]*$/.test(rest[1])) return null
  return resultUri
}

export function fetchWorkerResult(scope: RunScope, resultPath: string, signal?: AbortSignal): Promise<WorkerResult> {
  return requestJson(resultPath, input => {
    const result = validateWorkerResult(input)
    if (result.run_id !== scope.runId) throw new Error(`the result belongs to run ${result.run_id}.`)
    return result
  }, signal)
}

/** Text artifacts (logs, reports, patches) are read as plain text and rendered as text, never as HTML. */
export async function fetchArtifactText(scope: RunScope, artifactId: string, signal?: AbortSignal): Promise<string> {
  const response = await request(paths.artifact(scope, artifactId), signal, 'text/plain, */*')
  return response.text()
}

import { useCallback, useState } from 'react'
import {
  fetchArtifactText,
  fetchWorkerResult,
  paths,
  scopedResultPath,
  type RunDetail,
  type RunScope,
  type WorkerResult,
  type WorkflowEvent,
} from './api.ts'
import { ErrorPanel, LoadingPanel, StatusBadge } from './panels.tsx'
import { formatTime, KIND_LABEL, nodeStatusMeaning, STATUS_LABEL } from './status.ts'
import { useResource, type Resource } from './useResource.ts'

type DefinitionNode = RunDetail['definition']['nodes'][number]
type SnapshotNode = RunDetail['snapshot']['nodes'][number]

type Props = {
  scope: RunScope
  definition: DefinitionNode
  node: SnapshotNode
  events: Resource<WorkflowEvent[]>
  onRetryEvents: () => void
  refreshToken: number
}

function shortSha(value: string | null): string {
  return value === null ? 'none' : value.slice(0, 12)
}

/** Text-like artifact kinds are shown as plain text on demand; screenshots are images; anything else is only listed. */
function TextArtifact({ scope, artifactId }: { scope: RunScope; artifactId: string }) {
  const [open, setOpen] = useState(false)
  const load = useCallback((signal: AbortSignal) => fetchArtifactText(scope, artifactId, signal), [scope, artifactId])
  const { state, reload } = useResource(open ? `artifact:${artifactId}` : null, load)
  return (
    <div className="artifact-text">
      <button type="button" className="button button-small" aria-expanded={open} onClick={() => setOpen(previous => !previous)}>
        {open ? 'Hide contents' : 'Show contents'}
      </button>
      {open && state.status === 'loading' && <LoadingPanel>Loading artifact {artifactId}…</LoadingPanel>}
      {open && state.status === 'error' && <ErrorPanel error={state.error} what={`Artifact ${artifactId}`} onRetry={reload} />}
      {open && state.status === 'ready' && (
        state.data.length === 0
          ? <p className="projects-muted">This artifact is empty.</p>
          : <pre className="artifact-log" data-testid={`artifact-text:${artifactId}`} tabIndex={0}>{state.data}</pre>
      )}
    </div>
  )
}

function ScreenshotArtifact({ scope, artifactId }: { scope: RunScope; artifactId: string }) {
  const [failed, setFailed] = useState(false)
  if (failed) return <p className="projects-error-inline" role="alert">Screenshot {artifactId} could not be loaded from the artifact route.</p>
  return (
    <img
      className="artifact-screenshot"
      src={paths.artifact(scope, artifactId)}
      alt={`Screenshot artifact ${artifactId}`}
      data-testid={`artifact-screenshot:${artifactId}`}
      onError={() => setFailed(true)}
    />
  )
}

function WorkerEvidence({ scope, result, node }: { scope: RunScope; result: WorkerResult; node: SnapshotNode }) {
  const artifactsById = new Map(result.artifacts.map(artifact => [artifact.artifact_id, artifact]))
  const checkLogs = new Set(result.checks.map(check => check.log_artifact_id))
  const screenshots = result.artifacts.filter(artifact => artifact.kind === 'screenshot')
  // Check logs are shown with their check; everything else that is not a screenshot is listed here.
  const others = result.artifacts.filter(artifact => artifact.kind !== 'screenshot' && !checkLogs.has(artifact.artifact_id))
  return (
    <div className="worker-evidence" data-testid="worker-result">
      <dl className="projects-facts">
        <div><dt>Result status</dt><dd><StatusBadge status={result.status} /></dd></div>
        <div><dt>Result attempt</dt><dd>{result.attempt}{result.attempt !== node.attempt ? ` (graph node attempt is ${node.attempt})` : ''}</dd></div>
        <div><dt>Session</dt><dd><code>{result.session_id}</code></dd></div>
        <div><dt>Base commit</dt><dd><code>{shortSha(result.base_commit)}</code></dd></div>
        <div><dt>Output commit</dt><dd>{result.output_commit ? <code>{shortSha(result.output_commit)}</code> : 'None recorded (no durable output commit)'}</dd></div>
      </dl>
      <p className="worker-summary" data-testid="worker-summary">{result.summary}</p>
      {result.error && (
        <div className="projects-error" role="alert" data-testid="worker-error">
          <p><strong>Error {result.error.code}:</strong> {result.error.message}</p>
          <p>{result.error.retryable ? 'Marked retryable by the producer. Retrying is done through the workflow CLI, not this viewer.' : 'Marked not retryable by the producer.'}</p>
        </div>
      )}

      <section className="evidence-section" aria-labelledby="evidence-checks">
        <h4 id="evidence-checks">Checks actually executed</h4>
        {result.checks.length === 0 ? (
          <p className="projects-muted" data-testid="checks-empty">No checks were recorded for this result.</p>
        ) : (
          <ul className="evidence-list" data-testid="checks-list">
            {result.checks.map((check, index) => {
              const log = artifactsById.get(check.log_artifact_id)
              return (
                <li key={`${check.log_artifact_id}-${index}`} className={check.exit_code === 0 ? 'check check-passed' : 'check check-failed'} data-exit-code={check.exit_code}>
                  <div className="check-head">
                    <code className="check-command">{check.command}</code>
                    <span className="check-exit">{check.exit_code === 0 ? 'exit 0' : `exit ${check.exit_code} (failed)`}</span>
                  </div>
                  <p className="projects-muted check-meta">
                    {formatTime(check.started_at)} → {formatTime(check.finished_at)} · cwd <code>{check.cwd}</code>
                  </p>
                  <div className="check-log">
                    <span>Log artifact <code>{check.log_artifact_id}</code>{log ? '' : ' (not listed among the result artifacts)'}</span>
                    {log && <TextArtifact scope={scope} artifactId={log.artifact_id} />}
                  </div>
                </li>
              )
            })}
          </ul>
        )}
      </section>

      <section className="evidence-section" aria-labelledby="evidence-files">
        <h4 id="evidence-files">Changed files</h4>
        {result.changed_files.length === 0 ? (
          <p className="projects-muted" data-testid="changed-files-empty">No changed files were recorded.</p>
        ) : (
          <ul className="evidence-list evidence-files" data-testid="changed-files">
            {result.changed_files.map(file => <li key={file}><code>{file}</code></li>)}
          </ul>
        )}
      </section>

      <section className="evidence-section" aria-labelledby="evidence-assumptions">
        <h4 id="evidence-assumptions">Open assumptions</h4>
        {result.open_assumptions.length === 0 ? (
          <p className="projects-muted" data-testid="assumptions-empty">No open assumptions were recorded.</p>
        ) : (
          <ul className="evidence-list" data-testid="assumptions">
            {result.open_assumptions.map((assumption, index) => <li key={index}>{assumption}</li>)}
          </ul>
        )}
      </section>

      <section className="evidence-section" aria-labelledby="evidence-screenshots">
        <h4 id="evidence-screenshots">Screenshots</h4>
        {screenshots.length === 0 ? (
          <p className="projects-muted" data-testid="screenshots-empty">No screenshot artifacts were published.</p>
        ) : (
          <ul className="evidence-list evidence-screenshots" data-testid="screenshots">
            {screenshots.map(artifact => (
              <li key={artifact.artifact_id}>
                <p><code>{artifact.artifact_id}</code> <span className="projects-muted">sha256 {artifact.sha256.slice(0, 12)}…</span></p>
                <ScreenshotArtifact scope={scope} artifactId={artifact.artifact_id} />
              </li>
            ))}
          </ul>
        )}
      </section>

      <section className="evidence-section" aria-labelledby="evidence-artifacts">
        <h4 id="evidence-artifacts">Other artifacts</h4>
        {others.length === 0 ? (
          <p className="projects-muted">No artifacts beyond the check logs and screenshots were published.</p>
        ) : (
          <ul className="evidence-list" data-testid="artifacts">
            {others.map(artifact => (
              <li key={artifact.artifact_id}>
                <p><code>{artifact.artifact_id}</code> · {artifact.kind} · <span className="projects-muted">sha256 {artifact.sha256.slice(0, 12)}…</span></p>
                {artifact.kind === 'other'
                  ? <p className="projects-muted">Not rendered: only logs, reports, patches and screenshots are displayed.</p>
                  : <TextArtifact scope={scope} artifactId={artifact.artifact_id} />}
              </li>
            ))}
          </ul>
        )}
      </section>
    </div>
  )
}

/** Everything known about one node of a run: state, reuse evidence, result and events. Absent evidence is stated. */
export function NodeDetail({ scope, definition, node, events, onRetryEvents, refreshToken }: Props) {
  const resultPath = node.result_uri === null ? null : scopedResultPath(scope, node.result_uri)
  const loadResult = useCallback((signal: AbortSignal) => fetchWorkerResult(scope, resultPath!, signal), [scope, resultPath])
  const { state: result, reload: reloadResult } = useResource(resultPath, loadResult, refreshToken)

  const nodeEvents = events.status === 'ready' ? events.data.filter(event => event.node_id === node.node_id) : []
  const reuse = nodeEvents.filter(event => event.type === 'result_reused')
  const approvals = nodeEvents.filter(event => event.type === 'approval_requested')

  return (
    <section className="node-detail" aria-labelledby="node-detail-title" data-testid="node-detail" data-node-id={node.node_id}>
      <h3 id="node-detail-title">{definition.label} <span className="projects-muted node-detail-id">({node.node_id})</span></h3>
      <dl className="projects-facts">
        <div><dt>Kind</dt><dd>{KIND_LABEL[definition.kind]}</dd></div>
        <div><dt>Status</dt><dd><StatusBadge status={node.status} /> <span data-testid="node-status-meaning">{nodeStatusMeaning(definition.kind, node.status)}</span></dd></div>
        <div><dt>Graph attempt</dt><dd data-testid="node-attempt">{node.attempt === 0 ? '0 (not started)' : node.attempt}</dd></div>
        <div><dt>Session</dt><dd>{node.session_id ? <code>{node.session_id}</code> : 'No session recorded'}</dd></div>
        <div><dt>Depends on</dt><dd>{definition.depends_on.length ? definition.depends_on.join(', ') : 'nothing'}</dd></div>
      </dl>

      {node.status === 'awaiting_approval' && (
        <div className="projects-notice" role="status" data-testid="awaiting-notice">
          <p><strong>Awaiting approval.</strong> This node is stopped at a decision that has not been recorded. Viewing does not approve it; decisions are made through the workflow CLI.</p>
          {approvals.length > 0 && (
            <ul className="evidence-list">
              {approvals.map(event => <li key={event.event_id}>Requested at {formatTime(event.occurred_at)}: {event.message}</li>)}
            </ul>
          )}
        </div>
      )}

      <section className="evidence-section" aria-labelledby="node-reuse">
        <h4 id="node-reuse">Reuse evidence</h4>
        {events.status === 'loading' && <LoadingPanel>Loading events…</LoadingPanel>}
        {events.status === 'error' && <p className="projects-muted">Events could not be loaded, so reuse cannot be determined.</p>}
        {events.status === 'ready' && (reuse.length === 0 ? (
          <p className="projects-muted" data-testid="reuse-none">No reuse evidence recorded: the attempts shown are this node's own graph attempts, not reused results.</p>
        ) : (
          <ul className="evidence-list" data-testid="reuse-list">
            {reuse.map(event => (
              <li key={event.event_id}>
                Attempt {event.attempt} reused the result of attempt {event.reused_from_attempt ?? 'unknown'} (event {event.sequence}, {formatTime(event.occurred_at)}): {event.message}
              </li>
            ))}
          </ul>
        ))}
      </section>

      <section className="evidence-section" aria-labelledby="node-result">
        <h4 id="node-result">Result</h4>
        {node.result_uri === null && <p className="projects-muted" data-testid="result-none">No result has been published for this node{node.attempt === 0 ? ' (it has not started)' : ''}.</p>}
        {node.result_uri !== null && resultPath === null && (
          <p className="projects-error-inline" role="alert" data-testid="result-unscoped">
            The result link <code>{node.result_uri}</code> is outside this run's results route and was not fetched.
          </p>
        )}
        {resultPath !== null && result.status === 'loading' && <LoadingPanel>Loading the result…</LoadingPanel>}
        {resultPath !== null && result.status === 'error' && <ErrorPanel error={result.error} what="The node result" onRetry={reloadResult} />}
        {resultPath !== null && result.status === 'ready' && <WorkerEvidence scope={scope} result={result.data} node={node} />}
      </section>

      <section className="evidence-section" aria-labelledby="node-timeline">
        <h4 id="node-timeline">Events for this node</h4>
        {events.status === 'loading' && <LoadingPanel>Loading events…</LoadingPanel>}
        {events.status === 'error' && <ErrorPanel error={events.error} what="The run events" onRetry={onRetryEvents} />}
        {events.status === 'ready' && (nodeEvents.length === 0 ? (
          <p className="projects-muted" data-testid="events-none">No events reference this node.</p>
        ) : (
          <ol className="event-list" data-testid="node-events">
            {nodeEvents.map(event => (
              <li key={event.event_id}>
                <span className="event-seq">#{event.sequence}</span> <span className="projects-muted">{formatTime(event.occurred_at)}</span>{' '}
                <span className="event-type">{event.type.replace(/_/g, ' ')}</span>
                {event.status && <> · <StatusBadge status={event.status} /></>}
                {event.attempt > 0 && <> · attempt {event.attempt}</>}
                {event.message && <> — {event.message}</>}
                {event.artifact && <> · artifact <code>{event.artifact.artifact_id}</code> ({event.artifact.kind})</>}
              </li>
            ))}
          </ol>
        ))}
      </section>
      <p className="projects-muted node-detail-footnote">Status labels here are historical observations; “{STATUS_LABEL.succeeded}” on a worker node is not workflow completion.</p>
    </section>
  )
}

import type { ReactNode } from 'react'
import { describeApiError, ProjectsApiError } from './api.ts'
import { RUN_STATUS_MEANING, STATUS_LABEL, type RunStatus } from './status.ts'

export function StatusBadge({ status, explain = false }: { status: RunStatus; explain?: boolean }) {
  return (
    <span className={`status-badge status-${status}`} data-status={status}>
      <span>{STATUS_LABEL[status]}</span>
      {explain && <span className="visually-hidden">. {RUN_STATUS_MEANING[status]}</span>}
    </span>
  )
}

export function LoadingPanel({ children }: { children: ReactNode }) {
  return <p className="projects-loading" aria-busy="true">{children}</p>
}

/** A failed request: what failed, why, and what the reader can do. Never replaced by sample data. */
export function ErrorPanel({ error, what, onRetry, children }: { error: unknown; what: string; onRetry?: () => void; children?: ReactNode }) {
  const api = error instanceof ProjectsApiError ? error : null
  return (
    <div className="projects-error" role="alert" data-testid="projects-error" data-error-kind={api?.kind ?? 'unknown'}>
      <p><strong>{what} could not be loaded.</strong> {describeApiError(error)}</p>
      {api?.kind === 'http' && api.status !== null && api.status >= 500 && <p>The server reported a failure; nothing was substituted for the missing data. Retry once it has recovered.</p>}
      {api?.kind === 'malformed' && <p>The response was rejected rather than rendered, because it might be incomplete or from an incompatible server version.</p>}
      {api && <p className="projects-error-path">Request: <code>{api.path}</code></p>}
      <div className="projects-actions">
        {onRetry && <button type="button" className="button" onClick={onRetry}>Retry</button>}
        {children}
      </div>
    </div>
  )
}

export function EmptyPanel({ title, children, testId }: { title: string; children?: ReactNode; testId?: string }) {
  return (
    <div className="projects-empty" data-testid={testId}>
      <p><strong>{title}</strong></p>
      {children}
    </div>
  )
}

/** A link that navigates inside the app through history rather than reloading. */
export function AppLink({ href, onNavigate, className, children, current = false }: { href: string; onNavigate: (pathname: string) => void; className?: string; children: ReactNode; current?: boolean }) {
  return (
    <a
      href={href}
      className={className}
      aria-current={current ? 'page' : undefined}
      onClick={event => {
        if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey || event.button !== 0) return
        event.preventDefault()
        onNavigate(href)
      }}
    >
      {children}
    </a>
  )
}
/**
 * Human wording for run and node states. The wording deliberately separates "this node finished" from
 * "this workflow is complete": only a `succeeded` run is complete, and a worker node's success only means
 * its native session launched and ended its turn.
 */
import type { RunDetail } from './api.ts'

export type RunStatus = RunDetail['summary']['status']
export type NodeKind = RunDetail['definition']['nodes'][number]['kind']

export const STATUS_LABEL: Record<RunStatus, string> = {
  pending: 'Pending',
  running: 'Running',
  awaiting_approval: 'Awaiting approval',
  paused: 'Paused',
  succeeded: 'Succeeded',
  failed: 'Failed',
  cancelled: 'Cancelled',
}

/** What a run in this status means for the workflow as a whole. */
export const RUN_STATUS_MEANING: Record<RunStatus, string> = {
  pending: 'Nothing has started yet.',
  running: 'Work is in progress. The workflow is not complete.',
  awaiting_approval: 'Stopped at a decision that has not been made. The workflow is not complete; nothing is approved by viewing it.',
  paused: 'Paused with unresolved state (for example a session that could not be reconciled). The workflow is not complete.',
  succeeded: 'Integration was confirmed and no graph work remains.',
  failed: 'A graph step or check failed. The workflow did not complete.',
  cancelled: 'The run was cancelled before completion.',
}

/** What a node in this status means, given its kind. */
export function nodeStatusMeaning(kind: NodeKind, status: RunStatus): string {
  switch (status) {
    case 'pending': return 'Not started: no attempt has run.'
    case 'running': return kind === 'worker' ? 'The native worker session is running or its turn has not been signalled complete.' : 'In progress.'
    case 'awaiting_approval': return 'Waiting for an explicit decision recorded outside this viewer. Not complete.'
    case 'paused': return 'Paused with unresolved evidence. Not complete.'
    case 'succeeded':
      return kind === 'worker'
        ? 'The worker session launched and ended its turn. This is not workflow completion; verification, review and integration are separate nodes.'
        : kind === 'integration'
          ? 'This integration step completed.'
          : 'This step completed.'
    case 'failed': return 'This step failed. The run cannot succeed without intervention.'
    case 'cancelled': return 'This step was cancelled.'
  }
}

export const KIND_LABEL: Record<NodeKind, string> = {
  prepare: 'Preparation',
  worker: 'Worker',
  verification: 'Verification',
  review: 'Review',
  integration: 'Integration',
}

export function shortRevision(revision: string): string {
  return revision.slice(0, 12)
}

export function formatTime(iso: string): string {
  const time = Date.parse(iso)
  if (Number.isNaN(time)) return iso
  return new Date(time).toISOString().replace('T', ' ').replace(/\.\d{3}Z$/, ' UTC')
}
/**
 * Projects routes: `/projects[/<project>[/workflows/<workflow>[/runs/<run>[/nodes/<node>]]]]`.
 *
 * Every ID is an opaque contract identifier: it must match the shared ID pattern and is percent-encoded
 * as one path segment. Anything else is malformed rather than looked up. This domain is read-only and
 * separate from the Pi/Claude skill sources; nothing here names a filesystem path.
 */

/** Same pattern as the shared projects contract (`contracts/projects/v1.ts`). */
export const PROJECT_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/

export const PROJECTS_ROUTE = 'projects'

export type ProjectsRoute =
  | { level: 'projects' }
  | { level: 'project'; projectId: string }
  | { level: 'workflow'; projectId: string; workflowId: string }
  | { level: 'run'; projectId: string; workflowId: string; runId: string; nodeId: string | null }

export function isContractId(value: string): boolean {
  return PROJECT_ID_PATTERN.test(value)
}

function encode(segments: string[]): string {
  return `/${segments.map(encodeURIComponent).join('/')}`
}

export function projectsPathname(): string {
  return `/${PROJECTS_ROUTE}`
}

export function projectPathname(projectId: string): string {
  return encode([PROJECTS_ROUTE, projectId])
}

export function workflowPathname(projectId: string, workflowId: string): string {
  return encode([PROJECTS_ROUTE, projectId, 'workflows', workflowId])
}

export function runPathname(projectId: string, workflowId: string, runId: string, nodeId: string | null = null): string {
  const segments = [PROJECTS_ROUTE, projectId, 'workflows', workflowId, 'runs', runId]
  if (nodeId !== null) segments.push('nodes', nodeId)
  return encode(segments)
}

export function routeToPathname(route: ProjectsRoute): string {
  switch (route.level) {
    case 'projects': return projectsPathname()
    case 'project': return projectPathname(route.projectId)
    case 'workflow': return workflowPathname(route.projectId, route.workflowId)
    case 'run': return runPathname(route.projectId, route.workflowId, route.runId, route.nodeId)
  }
}

/** Whether a pathname belongs to the Projects domain at all (decided before any decoding). */
export function isProjectsPathname(pathname: string): boolean {
  const first = pathname.split('/').filter(segment => segment !== '')[0]
  return first === PROJECTS_ROUTE
}

/**
 * Parses a Projects pathname. Returns null when it is not a Projects pathname or when any segment is
 * malformed (bad encoding, an invalid ID, an unexpected literal or trailing segments).
 */
export function parseProjectsPathname(pathname: string): ProjectsRoute | null {
  const raw = pathname.split('/').filter(segment => segment !== '')
  if (raw[0] !== PROJECTS_ROUTE) return null
  let segments: string[]
  try {
    segments = raw.slice(1).map(decodeURIComponent)
  } catch {
    return null
  }
  if (segments.length === 0) return { level: 'projects' }
  const [projectId, workflowsLiteral, workflowId, runsLiteral, runId, nodesLiteral, nodeId, ...rest] = segments
  if (!isContractId(projectId)) return null
  if (workflowsLiteral === undefined) return { level: 'project', projectId }
  if (workflowsLiteral !== 'workflows' || workflowId === undefined || !isContractId(workflowId)) return null
  if (runsLiteral === undefined) return { level: 'workflow', projectId, workflowId }
  if (runsLiteral !== 'runs' || runId === undefined || !isContractId(runId)) return null
  if (nodesLiteral === undefined) return { level: 'run', projectId, workflowId, runId, nodeId: null }
  if (nodesLiteral !== 'nodes' || nodeId === undefined || !isContractId(nodeId) || rest.length > 0) return null
  return { level: 'run', projectId, workflowId, runId, nodeId }
}
import { useCallback, useEffect, useRef, useState } from 'react'

export type Resource<T> =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'ready'; data: T }
  | { status: 'error'; error: unknown }

/**
 * Loads one read-only resource identified by `key`. A null key means nothing to load. Changing the key or
 * calling `reload` starts a fresh request and abandons the previous one; a stale response never wins
 * because every settled value is tagged with the request token that produced it.
 * `refreshToken` forces a reload without changing the key (the header Refresh button).
 */
export function useResource<T>(key: string | null, load: (signal: AbortSignal) => Promise<T>, refreshToken = 0): { state: Resource<T>; reload: () => void } {
  const [settled, setSettled] = useState<{ token: string; value: Resource<T> } | null>(null)
  const [attempt, setAttempt] = useState(0)
  const loadRef = useRef(load)
  useEffect(() => { loadRef.current = load }, [load])
  const token = key === null ? null : `${key}\u0000${attempt}\u0000${refreshToken}`

  useEffect(() => {
    if (token === null) return
    const controller = new AbortController()
    loadRef.current(controller.signal).then(
      data => { if (!controller.signal.aborted) setSettled({ token, value: { status: 'ready', data } }) },
      error => { if (!controller.signal.aborted) setSettled({ token, value: { status: 'error', error } }) },
    )
    return () => controller.abort()
  }, [token])

  const reload = useCallback(() => setAttempt(previous => previous + 1), [])
  const state: Resource<T> = token === null ? { status: 'idle' } : settled?.token === token ? settled.value : { status: 'loading' }
  return { state, reload }
}

import { useCallback, useEffect, useMemo, useState } from 'react'
import { Breadcrumbs, type PathCrumb } from '../graph/Breadcrumbs.tsx'
import { fetchProjects, fetchRunDetail, fetchRuns, fetchWorkflows, ProjectsApiError, type RunPage, type RunSummary } from './api.ts'
import { AppLink, EmptyPanel, ErrorPanel, LoadingPanel, StatusBadge } from './panels.tsx'
import { projectPathname, projectsPathname, runPathname, workflowPathname, type ProjectsRoute } from './routes.ts'
import { RunView } from './RunView.tsx'
import { formatTime, shortRevision } from './status.ts'
import { useResource } from './useResource.ts'
import { WorkflowGraph } from './WorkflowGraph.tsx'

type Props = {
  /** Null when the pathname is under /projects but malformed. */
  route: ProjectsRoute | null
  refreshToken: number
  onNavigate: (pathname: string) => void
  onAnnounce: (message: string) => void
}

/**
 * The Projects root: registered projects, their workflow definitions and runs, read-only. Every level
 * loads from the scoped API and shows loading, empty, not-found and failure states in place; nothing
 * is ever substituted from fixtures.
 */
export function ProjectsView({ route, refreshToken, onNavigate, onAnnounce }: Props) {
  const projectId = route && route.level !== 'projects' ? route.projectId : null
  const workflowId = route && (route.level === 'workflow' || route.level === 'run') ? route.workflowId : null
  const runId = route && route.level === 'run' ? route.runId : null
  const nodeId = route && route.level === 'run' ? route.nodeId : null

  const { state: projects, reload: reloadProjects } = useResource('projects', fetchProjects, refreshToken)
  const loadWorkflows = useCallback((signal: AbortSignal) => fetchWorkflows(projectId!, signal), [projectId])
  const { state: workflows, reload: reloadWorkflows } = useResource(projectId === null ? null : `workflows:${projectId}`, loadWorkflows, refreshToken)
  const loadRuns = useCallback((signal: AbortSignal) => fetchRuns(projectId!, workflowId!, {}, signal), [projectId, workflowId])
  const runsKey = workflowId === null ? null : `runs:${projectId}/${workflowId}`
  const { state: firstPage, reload: reloadRuns } = useResource(runsKey, loadRuns, refreshToken)
  const scope = useMemo(() => (projectId === null || workflowId === null || runId === null ? null : { projectId, workflowId, runId }), [projectId, workflowId, runId])
  const loadDetail = useCallback((signal: AbortSignal) => fetchRunDetail({ projectId: projectId!, workflowId: workflowId!, runId: runId! }, signal), [projectId, workflowId, runId])
  const { state: detail, reload: reloadDetail } = useResource(scope === null ? null : `run:${scope.projectId}/${scope.workflowId}/${scope.runId}`, loadDetail, refreshToken)

  // Additional run pages are appended on demand; they belong to exactly one loaded first page and are dropped with it.
  const firstPageData = firstPage.status === 'ready' ? firstPage.data : null
  const [morePages, setMorePages] = useState<{ base: RunPage | null; pages: RunPage[]; loading: boolean; error: unknown }>({ base: null, pages: [], loading: false, error: null })
  const extra = morePages.base !== null && morePages.base === firstPageData ? morePages : { base: firstPageData, pages: [], loading: false, error: null }
  const pages: RunPage[] = firstPageData ? [firstPageData, ...extra.pages] : []
  const runs: RunSummary[] = pages.flatMap(page => page.runs)
  const nextCursor = pages.length ? pages[pages.length - 1].nextCursor : null
  const loadMore = async () => {
    if (!nextCursor || projectId === null || workflowId === null || firstPageData === null) return
    setMorePages({ ...extra, base: firstPageData, loading: true, error: null })
    try {
      const page = await fetchRuns(projectId, workflowId, { cursor: nextCursor })
      setMorePages(previous => (previous.base === firstPageData ? { ...previous, pages: [...previous.pages, page], loading: false } : previous))
    } catch (error) {
      setMorePages(previous => (previous.base === firstPageData ? { ...previous, loading: false, error } : previous))
    }
  }

  const projectName = projects.status === 'ready' && projectId !== null ? projects.data.find(project => project.project_id === projectId)?.name ?? projectId : projectId
  const currentWorkflow = workflows.status === 'ready' && workflowId !== null ? workflows.data.find(workflow => workflow.workflow_id === workflowId) ?? null : null
  const workflowName = currentWorkflow?.name ?? workflowId

  useEffect(() => {
    if (route === null) onAnnounce('This Projects link is invalid.')
    else if (route.level === 'projects' && projects.status === 'ready') onAnnounce(`Loaded ${projects.data.length} ${projects.data.length === 1 ? 'project' : 'projects'}.`)
    else if (route.level === 'project' && workflows.status === 'ready') onAnnounce(`Loaded ${workflows.data.length} ${workflows.data.length === 1 ? 'workflow' : 'workflows'} for ${projectName ?? route.projectId}.`)
    else if (route.level === 'workflow' && firstPage.status === 'ready') onAnnounce(`Loaded ${firstPage.data.runs.length} ${firstPage.data.runs.length === 1 ? 'run' : 'runs'} for ${workflowName ?? route.workflowId}.`)
    else if (route.level === 'run' && detail.status === 'ready') onAnnounce(`Loaded run ${route.runId}: ${detail.data.summary.status.replace('_', ' ')}.`)
    else if ((projects.status === 'error') || workflows.status === 'error' || firstPage.status === 'error' || detail.status === 'error') onAnnounce('Loading failed.')
  }, [route, projects, workflows, firstPage, detail, projectName, workflowName, onAnnounce])

  const crumbs: PathCrumb[] = [{ id: 'home', label: 'Home', pathname: '/' }, { id: 'projects', label: 'Projects', pathname: projectsPathname() }]
  if (projectId !== null) crumbs.push({ id: `project:${projectId}`, label: projectName ?? projectId, pathname: projectPathname(projectId) })
  if (projectId !== null && workflowId !== null) crumbs.push({ id: `workflow:${workflowId}`, label: workflowName ?? workflowId, pathname: workflowPathname(projectId, workflowId) })
  if (projectId !== null && workflowId !== null && runId !== null) crumbs.push({ id: `run:${runId}`, label: runId, pathname: runPathname(projectId, workflowId, runId) })
  if (route === null) crumbs.push({ id: 'invalid', label: 'Invalid link' })

  const notFound = (error: unknown) => error instanceof ProjectsApiError && error.notFound

  let info: string
  if (route === null) info = 'This Projects link is invalid.'
  else if (route.level === 'projects') info = 'Registered projects. Read-only: runs are started, approved and retried from the workflow CLI, never from this page.'
  else if (route.level === 'project') info = 'Workflow definitions registered for this project.'
  else if (route.level === 'workflow') info = 'Runs of this workflow, newest first. Each run keeps the definition it was started with.'
  else info = nodeId === null ? 'Run detail with its pinned definition graph.' : `Run detail, inspecting node ${nodeId}.`

  const busy = projects.status === 'loading' || workflows.status === 'loading' || firstPage.status === 'loading' || detail.status === 'loading'

  let content: React.ReactNode
  if (route === null) {
    content = (
      <div className="projects-error" role="alert">
        <p>This Projects link is invalid and could not be read. Links look like /projects/&lt;project&gt;/workflows/&lt;workflow&gt;/runs/&lt;run&gt;.</p>
        <p className="projects-actions"><AppLink href={projectsPathname()} onNavigate={onNavigate}>Go to Projects</AppLink></p>
      </div>
    )
  } else if (route.level === 'projects') {
    if (projects.status === 'loading' || projects.status === 'idle') content = <LoadingPanel>Loading registered projects…</LoadingPanel>
    else if (projects.status === 'error') content = <ErrorPanel error={projects.error} what="The project list" onRetry={reloadProjects} />
    else if (projects.data.length === 0) {
      content = (
        <EmptyPanel title="No projects are registered." testId="empty-projects">
          <p>The backend's project registry is empty. Projects are registered by the operator in the server configuration, not from this page.</p>
        </EmptyPanel>
      )
    } else {
      content = (
        <section aria-labelledby="projects-title">
          <h2 id="projects-title">Projects</h2>
          <ul className="projects-list" data-testid="projects-list">
            {projects.data.map(project => (
              <li key={project.project_id}>
                <AppLink href={projectPathname(project.project_id)} onNavigate={onNavigate} className="projects-card">
                  <span className="projects-card-title">{project.name}</span>
                  <span className="projects-muted">{project.project_id}</span>
                </AppLink>
              </li>
            ))}
          </ul>
        </section>
      )
    }
  } else if (route.level === 'project') {
    if (workflows.status === 'loading' || workflows.status === 'idle') content = <LoadingPanel>Loading workflows of {projectName}…</LoadingPanel>
    else if (workflows.status === 'error' && notFound(workflows.error)) {
      content = (
        <div className="projects-error" role="alert" data-testid="not-found">
          <p><strong>Project “{route.projectId}” is not registered.</strong> The API has no project with this ID; it may have been removed from the registry or the link may be wrong.</p>
          <p className="projects-actions"><AppLink href={projectsPathname()} onNavigate={onNavigate}>Go to Projects</AppLink></p>
        </div>
      )
    } else if (workflows.status === 'error') content = <ErrorPanel error={workflows.error} what={`The workflows of ${projectName}`} onRetry={reloadWorkflows} />
    else if (workflows.data.length === 0) {
      content = (
        <EmptyPanel title={`${projectName} has no workflow definitions.`} testId="empty-workflows">
          <p>The project is registered but no workflow is configured for it, so there is nothing to run or inspect here.</p>
        </EmptyPanel>
      )
    } else {
      content = (
        <section aria-labelledby="workflows-title">
          <h2 id="workflows-title">{projectName}: workflows</h2>
          <ul className="projects-list" data-testid="workflows-list">
            {workflows.data.map(workflow => (
              <li key={workflow.workflow_id}>
                <AppLink href={workflowPathname(route.projectId, workflow.workflow_id)} onNavigate={onNavigate} className="projects-card">
                  <span className="projects-card-title">{workflow.name}</span>
                  <span className="projects-muted">{workflow.workflow_id} · {workflow.nodes.length} {workflow.nodes.length === 1 ? 'node' : 'nodes'} · current revision {shortRevision(workflow.definition_revision)}</span>
                </AppLink>
              </li>
            ))}
          </ul>
        </section>
      )
    }
  } else if (route.level === 'workflow') {
    if (firstPage.status === 'loading' || firstPage.status === 'idle') content = <LoadingPanel>Loading runs of {workflowName}…</LoadingPanel>
    else if (firstPage.status === 'error' && notFound(firstPage.error)) {
      content = (
        <div className="projects-error" role="alert" data-testid="not-found">
          <p><strong>Workflow “{route.workflowId}” was not found in project “{route.projectId}”.</strong> Either the project is not registered or this workflow does not belong to it.</p>
          <p className="projects-actions">
            <AppLink href={projectPathname(route.projectId)} onNavigate={onNavigate}>Go to the project</AppLink>
            <AppLink href={projectsPathname()} onNavigate={onNavigate}>Go to Projects</AppLink>
          </p>
        </div>
      )
    } else if (firstPage.status === 'error') content = <ErrorPanel error={firstPage.error} what={`The runs of ${workflowName}`} onRetry={reloadRuns} />
    else {
      content = (
        <div className="workflow-view">
          <section aria-labelledby="runs-title">
            <h2 id="runs-title">{workflowName}: runs</h2>
            {runs.length === 0 ? (
              <EmptyPanel title="No runs have been recorded for this workflow." testId="empty-runs">
                <p>The workflow definition exists (see its current graph below) but it has never been run, or its runs are stored elsewhere. Runs are started from the workflow CLI.</p>
              </EmptyPanel>
            ) : (
              <ul className="projects-list run-list" data-testid="run-list">
                {runs.map(run => (
                  <li key={run.run_id} data-run-id={run.run_id} data-status={run.status}>
                    <AppLink href={runPathname(route.projectId, route.workflowId, run.run_id)} onNavigate={onNavigate} className="projects-card">
                      <span className="projects-card-title">{run.run_id} <StatusBadge status={run.status} explain /></span>
                      <span className="projects-muted">updated {formatTime(run.updated_at)} · created {formatTime(run.created_at)} · pinned revision {shortRevision(run.definition_revision)}</span>
                    </AppLink>
                  </li>
                ))}
              </ul>
            )}
            {nextCursor && (
              <div className="projects-actions">
                <button type="button" className="button" onClick={() => void loadMore()} disabled={extra.loading} aria-busy={extra.loading}>
                  {extra.loading ? 'Loading more runs…' : 'Load more runs'}
                </button>
              </div>
            )}
            {extra.error !== null && <ErrorPanel error={extra.error} what="The next page of runs" onRetry={() => void loadMore()} />}
          </section>
          <section aria-labelledby="definition-title" className="workflow-definition">
            <h3 id="definition-title">Current definition</h3>
            {workflows.status === 'loading' && <LoadingPanel>Loading the current definition…</LoadingPanel>}
            {workflows.status === 'error' && <ErrorPanel error={workflows.error} what="The current definition" onRetry={reloadWorkflows} />}
            {workflows.status === 'ready' && currentWorkflow === null && <p className="projects-error-inline" role="alert">The workflow list does not contain “{route.workflowId}”, so its current definition cannot be shown.</p>}
            {currentWorkflow && (
              <>
                <p className="projects-muted" data-testid="current-definition">{currentWorkflow.name} · revision <code>{shortRevision(currentWorkflow.definition_revision)}</code> · {currentWorkflow.nodes.length} nodes. Runs started before a definition change keep their own pinned graph.</p>
                <WorkflowGraph title={`Current definition graph of ${currentWorkflow.name}`} nodes={currentWorkflow.nodes} selectedId={null} />
              </>
            )}
          </section>
        </div>
      )
    }
  } else {
    const loading = detail.status === 'loading' || detail.status === 'idle'
    if (loading) content = <LoadingPanel>Loading run {route.runId}…</LoadingPanel>
    else if (detail.status === 'error' && notFound(detail.error)) {
      content = (
        <div className="projects-error" role="alert" data-testid="not-found">
          <p><strong>Run “{route.runId}” was not found in workflow “{route.workflowId}” of project “{route.projectId}”.</strong> Runs are only served under the project and workflow they belong to; a run of another project is not shown here.</p>
          <p className="projects-actions">
            <AppLink href={workflowPathname(route.projectId, route.workflowId)} onNavigate={onNavigate}>Go to the workflow's runs</AppLink>
            <AppLink href={projectsPathname()} onNavigate={onNavigate}>Go to Projects</AppLink>
          </p>
        </div>
      )
    } else if (detail.status === 'error') content = <ErrorPanel error={detail.error} what={`Run ${route.runId}`} onRetry={reloadDetail} />
    else content = <RunView scope={scope!} detail={detail.data} current={currentWorkflow} selectedNodeId={nodeId} refreshToken={refreshToken} onNavigate={onNavigate} />
  }

  return (
    <>
      <div className="navigation">
        <Breadcrumbs custom={{ crumbs, onNavigate }} selected={null} index={null} onNavigate={() => undefined} />
        <p className="folder-info" data-testid="projects-info">{info}</p>
      </div>
      <main className="workspace workspace-projects" aria-busy={busy} data-testid="projects-workspace">
        {content}
      </main>
    </>
  )
}

/**
 * Synthetic project/workflow/run data for the Projects viewer browser tests. Identifiers and the shape of
 * each run are shared by both verification phases: in `worker` mode they are served as explicit contract
 * payloads by `mock.ts`; in `candidate` mode `seed.ts` writes the same logical runs to disk in the format
 * the real backend adapter projects. Nothing here is real execution evidence.
 */
import { createHash } from 'node:crypto'
import { deflateSync } from 'node:zlib'
import { validateDefinition, validateRunDetail, type Project, type RunDetail, type WorkflowDefinition } from '../../contracts/projects/v1.ts'
import { eventSchema, validateWorkerResult, type WorkerResult, type WorkflowEvent } from '../../contracts/workflow/v1.ts'

export const PROJECT: Project = { project_id: 'alpha-project', name: 'Alpha project' }
export const EMPTY_PROJECT: Project = { project_id: 'empty-project', name: 'Empty project' }
export const WORKFLOW_ID = 'feature-flow'
