import { z } from 'zod'

// Source of truth. Exported JSON Schema is the language-neutral boundary.
const id = z.string().min(1)
const sha = z.string().regex(/^(?:[a-f0-9]{40}|[a-f0-9]{64})$/)
const timestamp = z.iso.datetime()
const relativePath = z.string().min(1).regex(/^(?!\/)(?![A-Za-z]:)(?!.*\\)(?!.*(?:^|\/)\.\.(?:\/|$)).+$/)
const status = z.enum(['pending', 'running', 'awaiting_approval', 'paused', 'succeeded', 'failed', 'cancelled'])
const envelope = { contract_version: z.literal('1.0.0'), run_id: id }

export const artifactSchema = z.strictObject({
  artifact_id: id,
  kind: z.enum(['patch', 'log', 'screenshot', 'test_report', 'other']),
  uri: z.string().min(1),
  sha256: z.string().regex(/^[a-f0-9]{64}$/),
})

export const checkSchema = z.strictObject({
  command: z.string().min(1),
  cwd: z.string().min(1),
  started_at: timestamp,
  finished_at: timestamp,
  exit_code: z.number().int(),
  log_artifact_id: id,
})

export const workerResultSchema = z.strictObject({
  ...envelope,
  node_id: id,
  attempt: z.number().int().positive(),
  session_id: id,
  status: z.enum(['succeeded', 'failed', 'cancelled']),
  base_commit: sha,
  output_commit: sha.nullable(),
  changed_files: z.array(relativePath),
  checks: z.array(checkSchema),
  open_assumptions: z.array(z.string().min(1)),
  artifacts: z.array(artifactSchema),
  summary: z.string().min(1),
  error: z.strictObject({ code: id, message: z.string().min(1), retryable: z.boolean() }).nullable(),
})

export const runSpecSchema = z.strictObject({
  ...envelope,
  objective: z.string().min(1),
  repository: z.string().min(1),
  base_commit: sha,
  max_concurrent_workers: z.number().int().min(1).max(2),
  workers: z.array(z.strictObject({
    node_id: id,
    executor: id,
    task: z.string().min(1),
    worktree: z.string().min(1),
    observed_start_commit: sha,
    owned_paths: z.array(relativePath).min(1),
    acceptance_criteria: z.array(z.string().min(1)).min(1),
  })).min(1).max(2),
  usage_exhaustion: z.strictObject({
    action: z.literal('pause_for_approval'),
    alternative_plan: z.string().min(1),
  }),
})

export const runSnapshotSchema = z.strictObject({
  ...envelope,
  status,
  last_sequence: z.number().int().nonnegative(),
  nodes: z.array(z.strictObject({
    node_id: id,
    kind: z.enum(['prepare', 'worker', 'verification', 'review', 'integration']),
    depends_on: z.array(id),
    status,
    attempt: z.number().int().nonnegative(),
    session_id: id.nullable(),
    result_uri: z.string().min(1).nullable(),
  })),
})

export const eventSchema = z.strictObject({
  ...envelope,
  event_id: id,
  sequence: z.number().int().positive(),
  occurred_at: timestamp,
  node_id: id.nullable(),
  attempt: z.number().int().nonnegative(),
  type: z.enum(['status_changed', 'log', 'artifact_published', 'result_published', 'approval_requested', 'result_reused', 'return_note']),
  status: status.nullable(),
  message: z.string(),
  artifact: artifactSchema.nullable(),
  result_uri: z.string().min(1).nullable(),
  reused_from_attempt: z.number().int().positive().nullable(),
})

export const controlRequestSchema = z.strictObject({
  ...envelope,
  request_id: id,
  expected_sequence: z.number().int().nonnegative(),
  action: z.enum(['approve', 'pause', 'resume', 'retry', 'cancel']),
  node_id: id.nullable(),
  reason: z.string().min(1),
})

export const schemas = {
  runSpec: runSpecSchema,
  workerResult: workerResultSchema,
  runSnapshot: runSnapshotSchema,
  event: eventSchema,
  controlRequest: controlRequestSchema,
}

export type RunSpec = z.infer<typeof runSpecSchema>
export type WorkerResult = z.infer<typeof workerResultSchema>
export type RunSnapshot = z.infer<typeof runSnapshotSchema>
export type WorkflowEvent = z.infer<typeof eventSchema>
export type ControlRequest = z.infer<typeof controlRequestSchema>

// Cross-field rules must also be implemented by non-TypeScript consumers.
export function validateRunSpec(input: unknown): RunSpec {
  const spec = runSpecSchema.parse(input)
  if (new Set(spec.workers.map(w => w.node_id)).size !== spec.workers.length)
    throw new Error('Worker node IDs must be unique')
  if (new Set(spec.workers.map(w => w.worktree)).size !== spec.workers.length)
    throw new Error('Workers require distinct worktrees')
  if (spec.workers.some(w => w.observed_start_commit !== spec.base_commit))
    throw new Error('Every worker must start at the exact base commit')
  return spec
}

export function validateWorkerResult(input: unknown): WorkerResult {
  const result = workerResultSchema.parse(input)
  const artifacts = new Map(result.artifacts.map(a => [a.artifact_id, a]))
  if (artifacts.size !== result.artifacts.length) throw new Error('Artifact IDs must be unique')
  for (const check of result.checks) {
    if (artifacts.get(check.log_artifact_id)?.kind !== 'log')
      throw new Error('Every executed check requires a log artifact')
    if (Date.parse(check.finished_at) < Date.parse(check.started_at))
      throw new Error('Check finish time precedes start time')
  }
  if (result.status === 'failed' && result.error === null)
    throw new Error('Failed results require an error')
  if (result.status === 'succeeded' && result.error !== null)
    throw new Error('Successful results cannot contain an error')
  if (result.status === 'succeeded' && result.output_commit === null)
    throw new Error('Successful workers require a durable output commit')
  return result
}

.app {
  height: 100%;
  display: flex;
  flex-direction: column;
  padding: 0 16px;
  gap: 8px;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

/* ---- Header, navigation, toolbar ---- */
.app-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding-top: 12px;
  flex-wrap: wrap;
}
.app-title h1 { margin: 0; font-size: 1.25rem; }
.app-title p { margin: 0; color: var(--text-muted); font-size: 0.85rem; }

.button {
  font: inherit;
  font-size: 0.875rem;
  color: var(--text);
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 6px 12px;
  min-width: 40px;
  min-height: 36px;
  cursor: pointer;
}
.button:hover:not(:disabled) { background: var(--surface-alt); }
.button:disabled { opacity: 0.5; cursor: default; }
.button[aria-pressed='true'] { background: var(--accent); color: var(--accent-contrast); border-color: var(--accent); }
.button:focus-visible, .breadcrumbs a:focus-visible, .breadcrumb-ellipsis:focus-visible, .missing a:focus-visible,
.outline button:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.navigation { display: flex; flex-direction: column; gap: 4px; }
.breadcrumbs ol { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; align-items: center; gap: 2px; }
.breadcrumbs li { display: flex; align-items: center; gap: 4px; min-height: 32px; }
.breadcrumbs a { color: var(--accent); text-decoration: none; padding: 4px 6px; border-radius: 4px; overflow-wrap: anywhere; }
.breadcrumbs a:hover { text-decoration: underline; }
.breadcrumbs a[aria-current='page'], .breadcrumb-current { color: var(--text); font-weight: 600; }
.breadcrumb-current { padding: 4px 6px; overflow-wrap: anywhere; }
.breadcrumb-separator { color: var(--text-muted); }
.breadcrumb-ellipsis { font: inherit; color: var(--accent); background: none; border: 1px solid var(--border); border-radius: 4px; padding: 2px 8px; cursor: pointer; }

.folder-info { margin: 0; color: var(--text-muted); font-size: 0.9rem; min-height: 1.4em; }

.missing { margin: 0; padding: 8px 12px; background: var(--danger-bg); border: 1px solid var(--danger-border); color: var(--danger-text); border-radius: 6px; }
.missing p { margin: 0; }
.missing-links { display: flex; gap: 12px; flex-wrap: wrap; margin-top: 4px; }
.missing a { color: var(--accent); }

.banner { padding: 8px 12px; border-radius: 6px; font-size: 0.9rem; }
.banner-error { background: var(--danger-bg); border: 1px solid var(--danger-border); color: var(--danger-text); }

.toolbar { display: flex; gap: 6px; flex-wrap: wrap; }

/* ---- Workspace ---- */
.workspace {
  flex: 1;
  min-height: 240px;
  position: relative;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--surface);
  overflow: hidden;
}
.placeholder { padding: 24px; color: var(--text-muted); display: flex; flex-direction: column; gap: 8px; align-items: flex-start; }
.placeholder p { margin: 0; }
.placeholder[role='alert'] { color: var(--danger-text); }

/* ---- Graph ---- */
.graph-canvas { width: 100%; height: 100%; display: block; touch-action: none; user-select: none; -webkit-user-select: none; }
.graph-background { fill: transparent; cursor: grab; }
.graph-background:active { cursor: grabbing; }

.edge { stroke: var(--edge); stroke-width: 1.5; }
.edge-highlight { stroke: var(--edge-highlight); stroke-width: 3; }
.edge-arrow { fill: var(--edge); }

.node-body { cursor: pointer; outline: none; }
.node-label { cursor: pointer; }
.node-file .node-body { cursor: pointer; }
.node .shape { stroke-width: 2; }
.node-source .shape { fill: var(--node-source-fill); stroke: var(--node-source-stroke); }
.node-directory .shape { fill: var(--node-directory-fill); stroke: var(--node-directory-stroke); stroke-linejoin: round; }
.node-file .shape { fill: var(--node-file-fill); stroke: var(--node-file-stroke); stroke-linejoin: round; }
.node-file .shape-detail { fill: none; stroke: var(--node-file-stroke); stroke-width: 1.5; }
.node-location .shape { fill: var(--node-location-fill); stroke: var(--node-location-stroke); stroke-linejoin: round; }
.node-location.is-unavailable .shape { fill: var(--surface-alt); stroke-dasharray: 5 4; }
.node .unavailable-tag { font-size: 10px; font-style: italic; fill: var(--danger-text); paint-order: stroke; stroke: var(--surface); stroke-width: 3px; }
.node.is-selected .shape { stroke: var(--accent); stroke-width: 4; }
.node .label { font-size: 12px; fill: var(--text); paint-order: stroke; stroke: var(--surface); stroke-width: 3px; stroke-linejoin: round; }
.node-source .label { font-size: 15px; font-weight: 700; stroke: none; }
.node .empty-tag { font-size: 10px; font-style: italic; fill: var(--text-muted); }
.focus-ring { fill: none; stroke: var(--focus); stroke-width: 3; stroke-dasharray: 4 3; display: none; }
.node-body:focus-visible .focus-ring { display: block; }

.node-toggle, .node-pin { cursor: pointer; outline: none; }
.node-toggle circle { fill: var(--surface); stroke: var(--text-muted); stroke-width: 1.5; }
.node-toggle path { stroke: var(--text); stroke-width: 2; stroke-linecap: round; fill: none; }
.node-toggle:hover circle, .node-toggle:focus-visible circle { stroke: var(--focus); stroke-width: 3; }
.node-pin circle { fill: var(--surface); stroke: var(--pin); stroke-width: 1.5; }
.node-pin path { fill: var(--pin); stroke: var(--pin); stroke-width: 1.5; stroke-linejoin: round; }
.node-pin:focus-visible circle { stroke: var(--focus); stroke-width: 3; }

/* ---- Legend ---- */
.legend { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 16px; padding-bottom: 8px; color: var(--text-muted); font-size: 0.8rem; }
.legend ul { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 4px 14px; }
.legend li { display: inline-flex; align-items: center; gap: 4px; }
.legend svg { width: 20px; height: 20px; }
.legend p { margin: 0; }
.legend-source { fill: var(--node-source-fill); stroke: var(--node-source-stroke); stroke-width: 2; }
.legend-directory { fill: var(--node-directory-fill); stroke: var(--node-directory-stroke); stroke-width: 2; }
.legend-file { fill: var(--node-file-fill); stroke: var(--node-file-stroke); stroke-width: 2; }
.legend-location { fill: var(--node-location-fill); stroke: var(--node-location-stroke); stroke-width: 2; }
.legend-edge { stroke: var(--edge); stroke-width: 2; }
.legend-edge-arrow { fill: var(--edge); }
.legend-pin { fill: var(--surface); stroke: var(--pin); stroke-width: 2; }
.legend-pin-glyph { fill: var(--pin); stroke: var(--pin); stroke-width: 1.5; }

/* ---- Outline ---- */
.outline { height: 100%; overflow: auto; padding: 12px; }
.outline-list { list-style: none; margin: 0; padding: 0; }
.outline-list .outline-list { padding-left: 22px; border-left: 1px solid var(--border); margin-left: 9px; }
.outline-row { display: flex; align-items: center; gap: 6px; min-height: 36px; flex-wrap: wrap; }
.outline-toggle { width: 28px; height: 28px; border: 1px solid var(--border); background: var(--surface); border-radius: 4px; cursor: pointer; display: inline-flex; align-items: center; justify-content: center; color: var(--text); }
.outline-toggle svg path { fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
.outline-name { font: inherit; color: var(--text); background: none; border: 1px solid transparent; border-radius: 4px; padding: 4px 8px; cursor: pointer; display: inline-flex; gap: 6px; align-items: center; overflow-wrap: anywhere; text-align: left; }
.outline-name:hover { background: var(--surface-alt); }
.outline-name[aria-current='true'] { border-color: var(--accent); background: var(--surface-alt); font-weight: 600; }
.outline-icon { color: var(--text-muted); }
.outline-file > .outline-row { padding-left: 34px; }
.outline-counts, .outline-empty { color: var(--text-muted); font-size: 0.85rem; }
.outline-empty { padding: 6px 8px; font-style: italic; }
.outline-unavailable { color: var(--danger-text); }

@media (max-width: 600px) {
  .app { padding: 0 12px; gap: 6px; }
  .app-title p { display: none; }
  .legend p { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; animation: none !important; }
}

/* ---- Document view ---- */
.workspace-document { overflow: auto; }
.document { display: flex; flex-direction: column; min-height: 100%; }
.document-header { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; flex-wrap: wrap; padding: 12px 16px; border-bottom: 1px solid var(--border); }
.document-identity { min-width: 0; }
.document-identity h2 { margin: 0; font-size: 1.15rem; overflow-wrap: anywhere; }
.document-identity h2:focus-visible, .document-source:focus-visible, .tab:focus-visible, .markdown a:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}
.document-meta { margin: 2px 0 0; color: var(--text-muted); font-size: 0.85rem; display: flex; gap: 6px; flex-wrap: wrap; overflow-wrap: anywhere; }
.document-source-name { font-weight: 600; }
.tabs { display: flex; gap: 4px; padding: 8px 16px 0; border-bottom: 1px solid var(--border); }
.tab { font: inherit; font-size: 0.9rem; color: var(--text-muted); background: none; border: 1px solid transparent; border-bottom: none; border-radius: 6px 6px 0 0; padding: 8px 14px; min-height: 36px; cursor: pointer; margin-bottom: -1px; }
.tab:hover { color: var(--text); background: var(--surface-alt); }
.tab[aria-selected='true'] { color: var(--text); background: var(--surface); border-color: var(--border); font-weight: 600; }
.document-panel { flex: 1; padding: 16px; min-width: 0; }
.document-message { margin: 0; color: var(--text-muted); }
.document-error { color: var(--danger-text); background: var(--danger-bg); border: 1px solid var(--danger-border); border-radius: 6px; padding: 12px; display: flex; flex-direction: column; gap: 8px; }
.document-error p { margin: 0; }
.document-actions { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
.document-source { margin: 0; padding: 12px; font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: 0.85rem; line-height: 1.5; white-space: pre; overflow: auto; background: var(--surface-alt); border: 1px solid var(--border); border-radius: 6px; tab-size: 4; }
.document-message + .document-source { margin-top: 12px; }

.markdown { max-width: 80ch; line-height: 1.6; overflow-wrap: anywhere; }
.markdown > :first-child { margin-top: 0; }
.markdown h1 { font-size: 1.5rem; }
.markdown h2 { font-size: 1.25rem; }
.markdown h3 { font-size: 1.1rem; }
.markdown a { color: var(--accent); }
.markdown pre { padding: 12px; background: var(--surface-alt); border: 1px solid var(--border); border-radius: 6px; overflow: auto; font-size: 0.85rem; line-height: 1.5; }
.markdown code { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: 0.9em; }
.markdown :not(pre) > code { background: var(--surface-alt); padding: 1px 4px; border-radius: 3px; }
.markdown blockquote { margin: 0; padding-left: 12px; border-left: 3px solid var(--border); color: var(--text-muted); }
.markdown .table-wrap { overflow: auto; }
.markdown table { border-collapse: collapse; }
.markdown th, .markdown td { border: 1px solid var(--border); padding: 4px 8px; text-align: left; vertical-align: top; }
.markdown th { background: var(--surface-alt); }
.markdown img { max-width: 100%; height: auto; }
.markdown img.image-unavailable { display: inline-block; min-width: 2em; min-height: 1.4em; padding: 2px 6px; border: 1px dashed var(--border); color: var(--text-muted); font-style: italic; font-size: 0.9em; }
.markdown input[type='checkbox'] { margin-right: 6px; }
.markdown hr { border: 0; border-top: 1px solid var(--border); }
.markdown .link-inert { color: var(--text-muted); text-decoration: underline dotted; cursor: not-allowed; }

/* ---- Editing ---- */
.document-header-actions { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
.document-notice { margin: 0; padding: 8px 16px; color: var(--text-muted); font-size: 0.9rem; border-bottom: 1px solid var(--border); }
.document-installed { color: var(--text); background: var(--surface-alt); border-left: 4px solid var(--node-directory-stroke); }
.document-location { font-weight: 600; }
.document-editing { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.editor { display: flex; flex-direction: column; flex: 1; min-width: 0; }
.editor-toolbar { display: flex; align-items: flex-end; justify-content: space-between; gap: 8px; flex-wrap: wrap; border-bottom: 1px solid var(--border); padding-right: 16px; }
.editor-toolbar .tabs { border-bottom: none; }
.editor-actions { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; padding-bottom: 6px; }
.save-status { font-size: 0.85rem; padding: 4px 10px; border-radius: 999px; border: 1px solid var(--border); color: var(--text-muted); min-width: 70px; text-align: center; }
.save-status-unsaved { color: var(--text); border-color: var(--focus); }
.save-status-saving { color: var(--text); font-style: italic; }
.save-status-saved { color: var(--text); }
.save-status-error { color: var(--danger-text); background: var(--danger-bg); border-color: var(--danger-border); }
.editor-error { margin: 12px 16px 0; }
.editor-panel { flex: 1; padding: 16px; min-width: 0; }
.editor-host .cm-editor { min-height: 240px; }
.editor-host .cm-content, .editor-host .cm-gutter { min-height: 240px; }
@media (max-width: 600px) {
  .editor-toolbar { padding-right: 8px; }
  .editor-panel { padding: 8px; }
  .editor-actions { width: 100%; justify-content: flex-end; }
}

/* ---- Dialogs and recovery ---- */
.confirm-dialog { border: 1px solid var(--border); border-radius: 8px; padding: 0; background: var(--surface); color: var(--text); max-width: min(90vw, 480px); }
.confirm-dialog::backdrop { background: rgba(0, 0, 0, 0.45); }
.confirm-dialog form { padding: 16px; display: flex; flex-direction: column; gap: 12px; }
.confirm-dialog h2 { margin: 0; font-size: 1.05rem; }
.confirm-description p { margin: 0; }
.confirm-description .dialog-path { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; overflow-wrap: anywhere; }
.confirm-actions { display: flex; justify-content: flex-end; gap: 8px; flex-wrap: wrap; }
.button-danger { border-color: var(--danger-border); color: var(--danger-text); background: var(--danger-bg); }
.editor-fallback { margin: 12px 16px 0; display: flex; flex-direction: column; gap: 8px; }
.editor-fallback p { margin: 0; }
.editor-fallback textarea { width: 100%; font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: 0.85rem; color: var(--text); background: var(--surface-alt); border: 1px solid var(--border); border-radius: 6px; padding: 8px; box-sizing: border-box; }

/* ---- Operations ---- */
.toolbars { display: flex; flex-wrap: wrap; gap: 6px 16px; align-items: center; }
.banner { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.banner-info { background: var(--surface-alt); border: 1px solid var(--border); color: var(--text); }
.button-small { min-height: 30px; padding: 4px 10px; font-size: 0.8rem; }
.field { display: flex; flex-direction: column; gap: 4px; font-size: 0.9rem; }
.field input, .field select { font: inherit; color: var(--text); background: var(--surface); border: 1px solid var(--border); border-radius: 6px; padding: 8px; min-height: 36px; }
.field input:focus-visible, .field select:focus-visible, .confirm-dialog .button:focus-visible, .editor-fallback textarea:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}
.dialog-error { margin: 0; color: var(--danger-text); }

/* ---- Roots navigation (Pi, Claude, Projects) ---- */
.roots ul { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 4px; }
.roots a { display: inline-block; color: var(--accent); text-decoration: none; padding: 6px 12px; min-height: 36px; border: 1px solid var(--border); border-radius: 999px; background: var(--surface); }
.roots a:hover { background: var(--surface-alt); }
.roots a[aria-current='page'] { color: var(--accent-contrast); background: var(--accent); border-color: var(--accent); font-weight: 600; }
.roots a:focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; }

/* ---- Projects root ---- */
/* The Projects root is long-form reading: the page scrolls instead of an inner pane, so nothing is trapped in a small box. */
.app-projects { height: auto; min-height: 100%; }
.workspace-projects { overflow: visible; flex: 1 0 auto; padding: 16px; }
.workspace-projects h2 { margin: 0 0 8px; font-size: 1.15rem; overflow-wrap: anywhere; }
.workspace-projects h3 { margin: 16px 0 8px; font-size: 1rem; }
.workspace-projects h4 { margin: 12px 0 6px; font-size: 0.95rem; }
.workspace-projects a { color: var(--accent); }
.workspace-projects a:focus-visible, .workspace-projects .button:focus-visible, .workflow-node:focus-visible, .artifact-log:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}
.projects-muted { color: var(--text-muted); font-size: 0.9rem; }
.projects-warning { color: var(--danger-text); }
.projects-loading { margin: 0; color: var(--text-muted); }
.projects-actions { display: flex; flex-wrap: wrap; gap: 12px; align-items: center; margin: 8px 0 0; }
.projects-error { margin: 0 0 12px; padding: 10px 12px; background: var(--danger-bg); border: 1px solid var(--danger-border); color: var(--danger-text); border-radius: 6px; }
.projects-error p { margin: 0 0 6px; overflow-wrap: anywhere; }
.projects-error p:last-child { margin-bottom: 0; }
.projects-error-path code { font-size: 0.85rem; }
.projects-error-inline { margin: 0; color: var(--danger-text); overflow-wrap: anywhere; }
.projects-empty { padding: 12px; border: 1px dashed var(--border); border-radius: 6px; background: var(--surface-alt); }
.projects-empty p { margin: 0 0 6px; }
.projects-empty p:last-child { margin-bottom: 0; }
.projects-notice { margin: 8px 0; padding: 10px 12px; border: 1px solid var(--node-directory-stroke); background: var(--node-directory-fill); color: var(--text); border-radius: 6px; }
.projects-notice p { margin: 0 0 6px; }

.projects-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); }
.projects-card { display: flex; flex-direction: column; gap: 4px; padding: 10px 12px; border: 1px solid var(--border); border-radius: 8px; background: var(--surface); text-decoration: none; color: var(--text); min-height: 44px; overflow-wrap: anywhere; }
.projects-card:hover { background: var(--surface-alt); }
.projects-card-title { font-weight: 600; display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
.run-list { grid-template-columns: 1fr; }

.status-badge { display: inline-flex; align-items: center; gap: 4px; padding: 1px 8px; border-radius: 999px; font-size: 0.8rem; font-weight: 600; border: 1px solid var(--border); background: var(--surface-alt); color: var(--text); white-space: nowrap; }
.status-badge::before { content: ''; width: 8px; height: 8px; border-radius: 50%; background: var(--text-muted); }
.status-succeeded::before { background: var(--node-location-stroke); }
.status-failed { border-color: var(--danger-border); color: var(--danger-text); background: var(--danger-bg); }
.status-failed::before { background: var(--danger-text); }
.status-running::before { background: var(--accent); }
.status-awaiting_approval, .status-paused { border-color: var(--node-directory-stroke); }
.status-awaiting_approval::before, .status-paused::before { background: var(--node-directory-stroke); }
.status-cancelled::before { background: var(--text-muted); }

.projects-facts { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 6px 16px; margin: 8px 0; }
.projects-facts > div { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.projects-facts dt { font-size: 0.8rem; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.02em; }
.projects-facts dd { margin: 0; overflow-wrap: anywhere; }
.projects-facts code, .workspace-projects code { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: 0.85em; background: var(--surface-alt); padding: 1px 4px; border-radius: 3px; overflow-wrap: anywhere; }

/* Workflow DAG */
.workflow-graph-scroll { overflow: auto; border: 1px solid var(--border); border-radius: 8px; background: var(--surface-alt); padding: 4px; }
.workflow-graph { display: block; }
.workflow-edge { fill: none; stroke: var(--edge); stroke-width: 1.5; }
.workflow-edge-arrow { fill: var(--edge); }
.workflow-node { cursor: default; outline: none; }
.workflow-node[role='button'] { cursor: pointer; }
.workflow-node-shape { fill: var(--surface); stroke: var(--node-file-stroke); stroke-width: 1.5; }
.workflow-node-worker .workflow-node-shape { stroke: var(--node-source-stroke); }
.workflow-node-verification .workflow-node-shape { stroke: var(--node-directory-stroke); }
